<script setup>
import { ref } from 'vue'
const settings=ref({days30:true,days14:true,overdue:true});const saved=ref(false)
function save(){localStorage.setItem('calibration-settings',JSON.stringify(settings.value));saved.value=true;setTimeout(()=>saved.value=false,2500)}
</script>
<template><section class="page"><div class="section-heading"><div><h2>Настройки системы</h2><p>Параметры уведомлений и учётной записи.</p></div><button class="btn-primary" @click="save">{{saved?'Сохранено ✓':'Сохранить изменения'}}</button></div><div class="dashboard-grid"><div class="panel"><h3>Уведомления</h3><div class="setting-row"><div><b>Напоминание за 30 дней</b><p>Отправлять ответственному сотруднику</p></div><button class="switch" :class="{off:!settings.days30}" @click="settings.days30=!settings.days30"><span/></button></div><div class="setting-row"><div><b>Напоминание за 14 дней</b><p>Повторное письмо с задачей на поверку</p></div><button class="switch" :class="{off:!settings.days14}" @click="settings.days14=!settings.days14"><span/></button></div><div class="setting-row"><div><b>Уведомление о просрочке</b><p>Отправлять руководителю подразделения</p></div><button class="switch" :class="{off:!settings.overdue}" @click="settings.overdue=!settings.overdue"><span/></button></div></div><div class="panel"><h3>Интеграция с Mokky</h3><p class="panel-subtitle" style="margin-top:9px">Адрес REST API</p><div class="insight" style="margin-top:10px">https://0fa731f37739cb96.mokky.dev</div><p class="panel-subtitle" style="margin-top:15px">Коллекции: users, requests, equipment, calibrations, departments, employees, certificates.</p></div></div></section></template>
